import java.util.*;

public class Main {
    static final int INF = 1000000000;
    static int n, m;
    static int[][] cap = new int[2002][2002];
    static List<Integer>[] adj = new ArrayList[2002];
    static boolean[] visited = new boolean[2002];
    static int[] parent = new int[2002];

    static int[][] directions = { {1,0}, {0,1}, {-1,0}, {0,-1} };

    static int augment(int u) {
        if (u == 1) return INF;
        visited[u] = true;
        for (int v : adj[u]) {
            if (!visited[v] && cap[u][v] > 0) {
                int flow = augment(v);
                if (flow > 0) {
                    parent[v] = u;
                    return Math.min(flow, cap[u][v]);
                }
            }
        }
        return 0;
    }

    static int maxFlow() {
        int total = 0;
        while (true) {
            Arrays.fill(visited, false);
            int flow = augment(0);
            if (flow == 0) break;
            total += flow;
            int v = 1;
            while (v != 0) {
                int u = parent[v];
                cap[u][v] -= flow;
                cap[v][u] += flow;
                v = u;
            }
        }
        return total;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int size = sc.nextInt();
        int timeLimit = sc.nextInt();

        for (int i = 0; i < 2 * size * size + 2; i++) {
            adj[i] = new ArrayList<>();
            for (int j = 0; j < 2 * size * size + 2; j++) {
                cap[i][j] = 0;
            }
        }

        String[] sci = new String[size];
        String[] capLab = new String[size];
        int[][][] vert = new int[size][size][2];
        int malfunctionIdx = -1;

        n = 2;
        for (int i = 0; i < size; i++) {
            sci[i] = sc.next();
            for (int j = 0; j < size; j++) {
                char ch = sci[i].charAt(j);
                if (ch >= '1' && ch <= '9') {
                    cap[0][n] = ch - '0';
                    adj[0].add(n);
                    adj[n].add(0);
                    vert[i][j][0] = n++;
                } else if (ch == 'Z') {
                    malfunctionIdx = 100 * i + j;
                    sci[i] = sci[i].substring(0, j) + 'Y' + sci[i].substring(j + 1);
                }
            }
        }

        m = n;
        for (int i = 0; i < size; i++) {
            capLab[i] = sc.next();
            for (int j = 0; j < size; j++) {
                char ch = capLab[i].charAt(j);
                if (ch >= '1' && ch <= '9') {
                    cap[m][1] = ch - '0';
                    adj[m].add(1);
                    adj[1].add(m);
                    vert[i][j][1] = m++;
                }
            }
        }

        int[][] die = new int[size][size];
        for (int i = 0; i < size; i++) {
            Arrays.fill(die[i], timeLimit + 1);
        }
        die[malfunctionIdx / 100][malfunctionIdx % 100] = 0;

        Queue<Integer> q = new LinkedList<>();
        q.offer(malfunctionIdx);
        while (!q.isEmpty()) {
            int x = q.poll();
            int y = x % 100;
            x /= 100;
            for (int[] d : directions) {
                int nx = x + d[0];
                int ny = y + d[1];
                if (nx >= 0 && nx < size && ny >= 0 && ny < size && sci[nx].charAt(ny) != 'Y' && die[nx][ny] > die[x][y] + 1) {
                    die[nx][ny] = die[x][y] + 1;
                    q.offer(100 * nx + ny);
                }
            }
        }

        int[][] reach = new int[size][size];
        for (int i = 0; i < size; i++) {
            Arrays.fill(reach[i], timeLimit + 1);
        }

        for (int i = 0; i < size; i++) {
            for (int j = 0; j < size; j++) {
                if (sci[i].charAt(j) >= '1' && sci[i].charAt(j) <= '9') {
                    for (int x = 0; x < size; x++) {
                        Arrays.fill(reach[x], timeLimit + 1);
                    }
                    reach[i][j] = 0;
                    if (capLab[i].charAt(j) >= '1' && capLab[i].charAt(j) <= '9') {
                        cap[vert[i][j][0]][vert[i][j][1]] = INF;
                        adj[vert[i][j][0]].add(vert[i][j][1]);
                        adj[vert[i][j][1]].add(vert[i][j][0]);
                    }
                    Queue<Integer> q2 = new LinkedList<>();
                    q2.offer(100 * i + j);
                    while (!q2.isEmpty()) {
                        int x = q2.poll();
                        int y = x % 100;
                        x /= 100;
                        for (int[] d : directions) {
                            int nx = x + d[0];
                            int ny = y + d[1];
                            if (nx >= 0 && nx < size && ny >= 0 && ny < size && sci[nx].charAt(ny) != 'Y' && reach[nx][ny] > reach[x][y] + 1) {
                                if (capLab[nx].charAt(ny) >= '1' && capLab[nx].charAt(ny) <= '9') {
                                    if (reach[x][y] + 1 <= die[nx][ny]) {
                                        cap[vert[i][j][0]][vert[nx][ny][1]] = INF;
                                        adj[vert[i][j][0]].add(vert[nx][ny][1]);
                                        adj[vert[nx][ny][1]].add(vert[i][j][0]);
                                    }
                                }
                                if (reach[x][y] + 1 < die[nx][ny]) {
                                    reach[nx][ny] = reach[x][y] + 1;
                                    q2.offer(100 * nx + ny);
                                }
                            }
                        }
                    }
                }
            }
        }

        System.out.println(maxFlow());
        sc.close();
    }
}
